mapper.select:
SELECT r.id, r.resource_no, r.resource_name, r.cover_url, r.trade_type, r.price, r.price_unit, r.resource_status, r.category_id, r.village_id, r.publisher_id, r.view_count, r.favorite_count, r.create_time, c.category_name, v.village_name, COALESCE(u.real_name, CONCAT(LEFT(u.phone, 3), '****', RIGHT(u.phone, 4))) AS publisher_name, f.create_time AS favorite_time FROM biz_resource_favorite f JOIN biz_resource r ON r.id = f.resource_id AND r.deleted = 0 LEFT JOIN biz_resource_category c ON c.id = r.category_id LEFT JOIN sys_village v ON v.id = r.village_id JOIN sys_user u ON u.id = r.publisher_id WHERE f.user_id = #{userId}
AND r.resource_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY f.create_time DESC, f.id DESC
